27	    /**
28	     * The singleton instance representing a terminal, disposed state, don't leak it.
29	     */
30	    DISPOSED
31	    ;
32	
33	    /**
34	     * Checks if the given Disposable is the common {@link #DISPOSED} enum value.
35	     * @param d the disposable to check
36	     * @return true if d is {@link #DISPOSED}
37	     */
38	    public static boolean isDisposed(Disposable d) {
39	        return d == DISPOSED;
40	    }
41	
42	    /**
43	     * Atomically sets the field and disposes the old contents.
44	     * @param field the target field
45	     * @param d the new Disposable to set
46	     * @return true if successful, false if the field contains the {@link #DISPOSED} instance.
47	     */
48	    public static boolean set(AtomicReference<Disposable> field, Disposable d) {
49	        for (;;) {
50	            Disposable current = field.get();
51	            if (current == DISPOSED) {
52	                if (d != null) {
53	                    d.dispose();
54	                }
55	                return false;
56	            }
57	            if (field.compareAndSet(current, d)) {
58	                if (current != null) {
59	                    current.dispose();
60	                }
61	                return true;
62	            }
63	        }
64	    }
65	
66	    /**
67	     * Atomically sets the field to the given non-null Disposable and returns true
68	     * or returns false if the field is non-null.
69	     * If the target field contains the common DISPOSED instance, the supplied disposable
70	     * is disposed. If the field contains other non-null Disposable, an IllegalStateException
71	     * is signaled to the RxJavaPlugins.onError hook.
72	     * 
73	     * @param field the target field
74	     * @param d the disposable to set, not null
75	     * @return true if the operation succeeded, false
76	     */
77	    public static boolean setOnce(AtomicReference<Disposable> field, Disposable d) {
78	        Objects.requireNonNull(d, "d is null");
79	        if (!field.compareAndSet(null, d)) {
80	            d.dispose();
81	            if (field.get() != DISPOSED) {
82	                reportDisposableSet();
83	            }
84	            return false;
85	        }
86	        return true;
87	    }
88	
89	    /**
90	     * Atomically replaces the Disposable in the field with the given new Disposable
91	     * but does not dispose the old one.
92	     * @param field the target field to change
93	     * @param d the new disposable, null allowed
94	     * @return true if the operation succeeded, false if the target field contained
95	     * the common DISPOSED instance and the given disposable (if not null) is disposed.
96	     */
97	    public static boolean replace(AtomicReference<Disposable> field, Disposable d) {
98	        for (;;) {
99	            Disposable current = field.get();
100	            if (current == DISPOSED) {
