44	        final SingleObserver<? super Boolean> downstream;
45	        final Predicate<? super T> predicate;
46	
47	        Disposable upstream;
48	
49	        boolean done;
50	
51	        AllObserver(SingleObserver<? super Boolean> actual, Predicate<? super T> predicate) {
52	            this.downstream = actual;
53	            this.predicate = predicate;
54	        }
