66	            if (done) {
67	                return;
68	            }
69	            boolean b;
70	            try {
71	                b = predicate.test(t);
72	            } catch (Throwable e) {
73	                Exceptions.throwIfFatal(e);
74	                upstream.dispose();
75	                onError(e);
76	                return;
77	            }
78	            if (!b) {
79	                done = true;
